import { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import axios from 'axios';

interface Solicitacao {
  id: number;
  nome_solicitante: string;
  setor: string;
  titulo: string;
  local: string;
  descricao: string;
  status: string;
  prioridade: string | null;
  data_criacao: string;
}

interface Tecnico {
  id: number;
  nome: string;
  telefone: string;
  email: string;
  token: string;
  ativo: boolean;
}

export default function AdminDashboard() {
  const navigate = useNavigate();
  const [solicitacoes, setSolicitacoes] = useState<Solicitacao[]>([]);
  const [tecnicos, setTecnicos] = useState<Tecnico[]>([]);
  const [activeTab, setActiveTab] = useState('dashboard');
  const [novoTecnico, setNovoTecnico] = useState({
    nome: '',
    telefone: '',
    email: ''
  });
  const [mensagem, setMensagem] = useState<{ tipo: 'sucesso' | 'erro'; texto: string } | null>(null);
  const [prioridadeSelecionada, setPrioridadeSelecionada] = useState<{ [key: number]: string }>({});

  useEffect(() => {
    const token = localStorage.getItem('token');
    if (!token) {
      navigate('/admin/login');
      return;
    }

    carregarDados();
  }, [navigate]);

  const carregarDados = async () => {
    try {
      const token = localStorage.getItem('token');
      const config = { headers: { Authorization: `Bearer ${token}` } };

      const [solicitacoesRes, tecnicosRes] = await Promise.all([
        axios.get('http://localhost:3001/api/solicitacoes', config),
        axios.get('http://localhost:3001/api/admin/tecnicos', config)
      ]);

      setSolicitacoes(solicitacoesRes.data);
      setTecnicos(tecnicosRes.data);
    } catch (error) {
      console.error('Erro ao carregar dados:', error);
    }
  };

  const handleAprovarSolicitacao = async (id: number) => {
    if (!prioridadeSelecionada[id]) {
      setMensagem({ tipo: 'erro', texto: 'Selecione uma prioridade antes de aprovar' });
      return;
    }

    try {
      const token = localStorage.getItem('token');
      await axios.patch(
        `http://localhost:3001/api/admin/solicitacoes/${id}`,
        { status: 'aprovada', prioridade: prioridadeSelecionada[id] },
        { headers: { Authorization: `Bearer ${token}` } }
      );
      
      setMensagem({ tipo: 'sucesso', texto: 'Solicitação aprovada com sucesso!' });
      carregarDados();
    } catch (error) {
      setMensagem({ tipo: 'erro', texto: 'Erro ao aprovar solicitação' });
    }
  };

  const handleReprovarSolicitacao = async (id: number) => {
    try {
      const token = localStorage.getItem('token');
      await axios.patch(
        `http://localhost:3001/api/admin/solicitacoes/${id}`,
        { status: 'reprovada' },
        { headers: { Authorization: `Bearer ${token}` } }
      );
      
      setMensagem({ tipo: 'sucesso', texto: 'Solicitação reprovada' });
      carregarDados();
    } catch (error) {
      setMensagem({ tipo: 'erro', texto: 'Erro ao reprovar solicitação' });
    }
  };

  const handleCadastrarTecnico = async (e: React.FormEvent) => {
    e.preventDefault();
    try {
      const token = localStorage.getItem('token');
      const response = await axios.post(
        'http://localhost:3001/api/admin/tecnicos',
        novoTecnico,
        { headers: { Authorization: `Bearer ${token}` } }
      );

      setMensagem({
        tipo: 'sucesso',
        texto: `Técnico cadastrado com sucesso! Link de acesso: ${response.data.tecnico.link_acesso}`
      });
      setNovoTecnico({ nome: '', telefone: '', email: '' });
      carregarDados();
    } catch (error) {
      setMensagem({ tipo: 'erro', texto: 'Erro ao cadastrar técnico' });
    }
  };

  const handleLogout = () => {
    localStorage.removeItem('token');
    localStorage.removeItem('adminData');
    navigate('/admin/login');
  };

  const renderDashboard = () => (
    <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
      <div className="bg-white rounded-lg shadow p-6">
        <h3 className="text-lg font-medium mb-4">Solicitações Pendentes</h3>
        <div className="text-3xl font-bold text-blue-600">
          {solicitacoes.filter(s => s.status === 'pendente').length}
        </div>
      </div>
      <div className="bg-white rounded-lg shadow p-6">
        <h3 className="text-lg font-medium mb-4">Solicitações em Andamento</h3>
        <div className="text-3xl font-bold text-green-600">
          {solicitacoes.filter(s => s.status === 'aprovada').length}
        </div>
      </div>
      <div className="bg-white rounded-lg shadow p-6">
        <h3 className="text-lg font-medium mb-4">Técnicos Ativos</h3>
        <div className="text-3xl font-bold text-purple-600">
          {tecnicos.filter(t => t.ativo).length}
        </div>
      </div>
    </div>
  );

  const renderSolicitacoes = () => (
    <div className="bg-white shadow rounded-lg p-6">
      <h2 className="text-lg font-medium text-gray-900 mb-4">Solicitações Pendentes</h2>
      <div className="space-y-4">
        {solicitacoes
          .filter(s => s.status === 'pendente')
          .map(solicitacao => (
            <div key={solicitacao.id} className="border rounded-lg p-4">
              <h3 className="font-medium">{solicitacao.titulo}</h3>
              <p className="text-sm text-gray-500">
                Solicitante: {solicitacao.nome_solicitante} - Setor: {solicitacao.setor}
              </p>
              <p className="text-sm text-gray-500">Local: {solicitacao.local}</p>
              {solicitacao.descricao && (
                <p className="text-sm text-gray-500 mt-2">{solicitacao.descricao}</p>
              )}
              <div className="mt-4 flex items-center space-x-4">
                <select
                  className="text-sm border rounded p-2"
                  onChange={(e) => setPrioridadeSelecionada({ ...prioridadeSelecionada, [solicitacao.id]: e.target.value })}
                  value={prioridadeSelecionada[solicitacao.id] || ''}
                >
                  <option value="">Selecione a prioridade</option>
                  <option value="alta">Alta</option>
                  <option value="media">Média</option>
                  <option value="baixa">Baixa</option>
                </select>
                <button
                  onClick={() => handleAprovarSolicitacao(solicitacao.id)}
                  className="px-4 py-2 bg-green-600 text-white rounded hover:bg-green-700 text-sm"
                  disabled={!prioridadeSelecionada[solicitacao.id]}
                >
                  Aprovar
                </button>
                <button
                  onClick={() => handleReprovarSolicitacao(solicitacao.id)}
                  className="px-4 py-2 bg-red-600 text-white rounded hover:bg-red-700 text-sm"
                >
                  Reprovar
                </button>
              </div>
            </div>
          ))}
      </div>
    </div>
  );

  const renderTecnicos = () => (
    <div className="grid grid-cols-1 gap-6">
      <div className="bg-white shadow rounded-lg p-6">
        <h2 className="text-lg font-medium text-gray-900 mb-4">Cadastrar Novo Técnico</h2>
        <form onSubmit={handleCadastrarTecnico} className="space-y-4">
          <div>
            <label htmlFor="nome" className="block text-sm font-medium text-gray-700">
              Nome
            </label>
            <input
              type="text"
              id="nome"
              value={novoTecnico.nome}
              onChange={(e) => setNovoTecnico({ ...novoTecnico, nome: e.target.value })}
              className="mt-1 block w-full rounded-md border-gray-300 shadow-sm focus:border-blue-500 focus:ring-blue-500 sm:text-sm"
              required
            />
          </div>
          <div>
            <label htmlFor="telefone" className="block text-sm font-medium text-gray-700">
              Telefone
            </label>
            <input
              type="tel"
              id="telefone"
              value={novoTecnico.telefone}
              onChange={(e) => setNovoTecnico({ ...novoTecnico, telefone: e.target.value })}
              className="mt-1 block w-full rounded-md border-gray-300 shadow-sm focus:border-blue-500 focus:ring-blue-500 sm:text-sm"
              required
            />
          </div>
          <div>
            <label htmlFor="email" className="block text-sm font-medium text-gray-700">
              Email
            </label>
            <input
              type="email"
              id="email"
              value={novoTecnico.email}
              onChange={(e) => setNovoTecnico({ ...novoTecnico, email: e.target.value })}
              className="mt-1 block w-full rounded-md border-gray-300 shadow-sm focus:border-blue-500 focus:ring-blue-500 sm:text-sm"
              required
            />
          </div>
          <button
            type="submit"
            className="w-full flex justify-center py-2 px-4 border border-transparent rounded-md shadow-sm text-sm font-medium text-white bg-blue-600 hover:bg-blue-700 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-blue-500"
          >
            Cadastrar Técnico
          </button>
        </form>
      </div>

      <div className="bg-white shadow rounded-lg p-6">
        <h2 className="text-lg font-medium text-gray-900 mb-4">Técnicos Cadastrados</h2>
        <div className="space-y-4">
          {tecnicos.map(tecnico => (
            <div key={tecnico.id} className="border rounded-lg p-4">
              <h3 className="font-medium">{tecnico.nome}</h3>
              <p className="text-sm text-gray-500">Email: {tecnico.email}</p>
              <p className="text-sm text-gray-500">Telefone: {tecnico.telefone}</p>
              <p className="text-sm text-gray-500">Status: {tecnico.ativo ? 'Ativo' : 'Inativo'}</p>
            </div>
          ))}
        </div>
      </div>
    </div>
  );

  return (
    <div className="min-h-screen bg-gray-100 flex">
      {/* Sidebar */}
      <div className="w-64 bg-white shadow-lg">
        <div className="h-16 flex items-center justify-center border-b">
          <h1 className="text-xl font-semibold text-gray-900">Painel Admin</h1>
        </div>
        <nav className="mt-6">
          <div className="px-4 space-y-2">
            <button
              onClick={() => setActiveTab('dashboard')}
              className={`w-full flex items-center space-x-2 px-4 py-2 text-sm rounded-lg ${
                activeTab === 'dashboard' ? 'bg-blue-50 text-blue-600' : 'text-gray-600 hover:bg-gray-50'
              }`}
            >
              <span>Dashboard</span>
            </button>
            <button
              onClick={() => setActiveTab('solicitacoes')}
              className={`w-full flex items-center space-x-2 px-4 py-2 text-sm rounded-lg ${
                activeTab === 'solicitacoes' ? 'bg-blue-50 text-blue-600' : 'text-gray-600 hover:bg-gray-50'
              }`}
            >
              <span>Solicitações</span>
            </button>
            <button
              onClick={() => setActiveTab('tecnicos')}
              className={`w-full flex items-center space-x-2 px-4 py-2 text-sm rounded-lg ${
                activeTab === 'tecnicos' ? 'bg-blue-50 text-blue-600' : 'text-gray-600 hover:bg-gray-50'
              }`}
            >
              <span>Técnicos</span>
            </button>
          </div>
        </nav>
        <div className="absolute bottom-0 w-64 p-4 border-t">
          <button
            onClick={handleLogout}
            className="w-full flex items-center justify-center px-4 py-2 text-sm text-red-600 hover:text-red-900"
          >
            Sair
          </button>
        </div>
      </div>

      {/* Main Content */}
      <div className="flex-1">
        <main className="p-6">
          {mensagem && (
            <div className={`mb-4 rounded-md p-4 ${
              mensagem.tipo === 'sucesso' ? 'bg-green-50 text-green-700' : 'bg-red-50 text-red-700'
            }`}>
              <p className="text-sm">{mensagem.texto}</p>
            </div>
          )}

          {activeTab === 'dashboard' && renderDashboard()}
          {activeTab === 'solicitacoes' && renderSolicitacoes()}
          {activeTab === 'tecnicos' && renderTecnicos()}
        </main>
      </div>
    </div>
  );
}
